```html
<button id="miBtn">Haz click</button>

<script>
  const btn = document.getElementById('miBtn');

  function manejarClick(event) {
    alert('¡Botón pulsado!');
    // Evita que el botón recargue la página si está dentro de un form
    event.preventDefault();
  }

  btn.addEventListener('click', manejarClick);
</script>
```
